#include "stdafx.h"#include "ControlBuilderE.h"#include <Connect.h>#include <ConnectH.h>static bool bRegisteredFind = false;extern nRSUx::SParamInfo RsuConnectParamInfo( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix );extern bool GetFirstACSObject();extern bool GetNextACSObject( DWORD & Type, void ** pData, char Name[256], char Data[256] );extern bool ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData );KControlBuilderE::KControlBuilderE( LPCSTR ObjName ): IBaseModel( (char*)ObjName ), KControlBuilder( ObjName ){  TypeObj = RSU_Obj;  if( pRegisterFinderACSobj && !bRegisteredFind )  {    bRegisteredFind = true;    pRegisterFinderACSobj( ::GetFirstACSObject, ::GetNextACSObject, ::ShowACSObject );  }  if( pRegisterRsuConnection )    pRegisterRsuConnection( GetCsvPrefix(), RsuConnectParamInfo, NULL );}KControlBuilderE::~KControlBuilderE(){}int KControlBuilderE::Init( int ){  if( !pRegisterHWstructs )    LoadLibrary("HW5xxRegisterInSystem.dll");  if( pRegisterHWstructs )    pRegisterHWstructs();  return KControlBuilder::InitL();}int KControlBuilderE::Step0(){  return KControlBuilder::Step0L();}int KControlBuilderE::Step1(){  return KControlBuilder::Step1L();}int KControlBuilderE::StepT(double dt){  double dt_sec = dt * 3600.;  return KControlBuilder::StepTL( dt_sec );}